public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,3>CodeRanges{{{0x3bd6,0x3c10},{0x40b0,0x40c0},{0x4534,0x4554}}};bool active()const{return depth_||foreground_.active()||keys_.active()||adc_.active()||state_.active()||encoder_.active()||clock_.active();}void reset(){depth_=0;foreground_.reset();keys_.reset();adc_.reset();state_.reset();encoder_.reset();clock_.reset();steps_=0;}uint64_t steps()const{return steps_;}unsigned requestedChild()const{return depth_?jobs_[depth_-1].child:0;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(NativeUiEncoder::candidate(at)){if(!encoder_.step(c))return false;++steps_;return true;}if(NativeForegroundClock::candidate(at)||NativeDspTransfer::candidate(at)){if(!clock_.step(c))return false;++steps_;return true;}if(at>=0x9aa&&at<0x9b6){if(!foreground_.step(c).stepped)return false;++steps_;return true;}if(NativeStartupKeyboard::candidate(at)){if(!keys_.step(c))return false;++steps_;return true;}if(NativeStartupAdc::candidate(at)||(at>=0x65a&&at<0x670)){if(!adc_.step(c))return false;++steps_;return true;}if(NativeStartupState::candidate(at)){if(!state_.step(c))return false;++steps_;return true;}
 if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x40b0)j.task.emplace<M>();else if(at==0x4534)j.task.emplace<G>();else if(at==0x3bd6)j.task.emplace<Q>();else if(at==0x3be4)j.task.emplace<P>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K UI services capacity");jobs_[depth_++]=j;}
 auto&j=jobs_[depth_-1];std::visit([&](auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,G>){if(t.awaiting())t.resume(uint8_t(c.reg8(9)));}else if constexpr(std::is_same_v<V,P>){if(t.awaiting())t.resume(uint16_t(c.reg16(6)));}else if constexpr(std::is_same_v<V,Q>)if(t.awaiting())t.resume();},j.task);j.child=0;if(at!=boundary(j))throw std::logic_error("Native K UI service boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
 std::visit([&](auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,M>)t.advanceBefore(cost,cr,[&]{c.reg8(9)=c.read8(0xbb0e);val(c,c.reg8(9));return uint8_t(c.reg8(9));});else if constexpr(std::is_same_v<V,G>)t.advanceBefore(cost,cr,[&](bool page){auto r=page?1:9;c.reg8(r)=c.read8(page?0xcd70:0xcd72);val(c,c.reg8(r));return uint8_t(c.reg8(r));});else if constexpr(std::is_same_v<V,P>)t.advanceBefore(cost,cr,[&]{c.reg16(5)=int16_t(c.read16(0xcd6a));val(c,c.reg16(5));return uint16_t(c.reg16(5));},[&](unsigned value){c.write16(int16_t(value),0xcd6a);val(c,c.reg16(14));});else t.advanceBefore(cost,cr);},j.task);
 if(c.cycles-begin!=cost)throw std::logic_error("Native K UI service clocks differ");if(std::visit([](const auto&t){return t.complete();},j.task))--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;}
private:static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static bool waiting(const Job&j){return std::visit([](const auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,M>)return false;else return t.awaiting();},j.task);}static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,M>){static constexpr unsigned a[]={0x40b0,0x40b2,0x40b4,0x40b6,0x40bc,0x40be,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<V,G>){static constexpr unsigned a[]={0x4534,0x4536,0x453c,0x4542,0x4546,0x4548,0x454c,0x454e,0x4550,0x4552,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<V,Q>){static constexpr unsigned a[]={0x3bd6,0x3bda,0x3bde,0x3be2,0};return a[unsigned(t.stage())];}else{static constexpr unsigned a[]={0x3be4,0x3be8,0x3bea,0x3bf0,0x3bf2,0x3bf6,0x3bf8,0x3bfe,0x3c02,0x3c06,0x3c0a,0x3c0e,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){switch(boundary(j)){case 0x40b6:case 0x4536:case 0x453c:case 0x3bea:case 0x3bf8:return 6;case 0x4542:case 0x4548:case 0x3bd6:case 0x3bda:case 0x3bde:case 0x3be4:case 0x3bf2:case 0x3bfe:case 0x3c02:case 0x3c06:case 0x3c0a:return 4;default:return 2;}}
