 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;auto at=boundary(j);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,int(at+len-1));unsigned a=at==0x40bc?0xbb0e:at==0x4536?0xcd70:at==0x453c?0xcd72:0xcd6a;cr.read=bus(a,at==0x3bea?2:1,int(at+len-1));cr.write=bus(0xcd6a,2,c.writeHistory());return cr;}
 static void call(Job&j,Stage1Cpu&c,unsigned target,unsigned returned){j.child=target;midi_projection::call(c,target,returned,true);}
 static void project(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<M>(&j.task)){switch(t->stage()){case M::Stage::Field:c.reg8(9)=int8_t(0xb2);val(c,c.reg8(9));break;case M::Stage::ExtendWord:c.reg16(1)=uint8_t(c.reg8(9));val(c,c.reg16(1));break;case M::Stage::ExtendLong:c.reg32(1)=uint16_t(c.reg16(1));val(c,c.reg32(1));break;case M::Stage::Bind:c.reg32(1)=int32_t(midi_projection::arithmetic(c,uint32_t(c.reg32(1)),0xba5c,32,false));break;case M::Stage::Return:midi_projection::ret(c);break;default:break;}}
 else if(auto*t=std::get_if<G>(&j.task)){switch(t->stage()){case G::Stage::Clear:c.reg8(8)=0;val(c,0);break;case G::Stage::Compare:(void)midi_projection::arithmetic(c,uint16_t(c.reg16(1)),0x602,16,true);break;case G::Stage::Mode:call(j,c,0x40b0,0x454c);break;case G::Stage::Set:c.reg8(8)=1;val(c,1);break;case G::Stage::Test:val(c,c.reg8(8));break;case G::Stage::Return:midi_projection::ret(c);break;default:break;}}
 else if(auto*t=std::get_if<Q>(&j.task)){switch(t->stage()){case Q::Stage::Keyboard:call(j,c,0x452,0x3bda);break;case Q::Stage::Adc:call(j,c,0x58c,0x3bde);break;case Q::Stage::Panel:call(j,c,0x1e1c,0x3be2);break;case Q::Stage::Return:midi_projection::ret(c);break;default:break;}}
 else if(auto*t=std::get_if<P>(&j.task)){switch(t->stage()){case P::Stage::Tick:call(j,c,0x9aa,0x3be8);break;case P::Stage::RetainTick:c.reg16(14)=c.reg16(6);val(c,c.reg16(14));break;case P::Stage::Elapsed:c.reg16(6)=int16_t(midi_projection::arithmetic(c,uint16_t(c.reg16(6)),uint16_t(c.reg16(5)),16,true));break;case P::Stage::Compare:(void)midi_projection::arithmetic(c,uint16_t(c.reg16(6)),25,16,true);break;case P::Stage::Keyboard:call(j,c,0x4aa,0x3c02);break;case P::Stage::Adc:call(j,c,0x638,0x3c06);break;case P::Stage::Encoder:call(j,c,0x3b6e,0x3c0a);break;case P::Stage::Clock:call(j,c,0x1838,0x3c0e);break;case P::Stage::Return:midi_projection::ret(c);break;default:break;}}
 }
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeForeground foreground_;NativeStartupKeyboard keys_;NativeStartupAdc adc_;NativeStartupState state_;NativeUiEncoder encoder_;NativeForegroundClock clock_;
